// ---- 运行期查表 / 度量 helper（纯函数，确定性） ----
export function glyphHas(ch, weight = "regular") {
  const g = GLYPHS[weight] || GLYPHS.regular;
  return Object.prototype.hasOwnProperty.call(g, ch);
}
export function glyphEntry(ch, weight = "regular") {
  const g = GLYPHS[weight] || GLYPHS.regular;
  return g[ch] || g["?"];
}
export function glyphRowAlphas(row, w) {
  const out = [];
  for (let i = 0; i < row.length; i += 2) {
    const v = parseInt(row.slice(i, i + 2), 16);
    out.push(v >> 4, v & 15);
  }
  return out.slice(0, w);
}
export function glyphScale(px) { return px / GLYPH_BASE_H; }
export function measureGlyph(text, weight, px) {
  const s = glyphScale(px); let w = 0; const t = String(text);
  for (let i = 0; i < t.length; i++) {
    const e = glyphEntry(t[i], weight);
    w += Math.round(e[0] * s);
    if (i < t.length - 1) w += Math.round(GLYPH_GAP * s);
  }
  return w;
}
export function glyphLineHeight(px) { return Math.round(px); }
